        uint l_Fade;
    
        NotAvailableWhileMenuBuild();
        l_Pos = Pos(",", aOperand);
        if (l_Pos > 0)
        {
            l_Eval = TfurqExprEvaluator.Create(f_CurContext);
            try
            {
                l_Sub = Copy(aOperand, 1, (l_Pos - 1));
                l_Eval.Source = l_Sub;
                l_Volume = EnsureRange(l_Eval.ResultValue, 0, 255);
                l_Sub = Copy(aOperand, (l_Pos + 1), MaxInt);
                l_Eval.Source = l_Sub;
                l_Fade = EnsureRange(l_Eval.ResultValue, 0, MaxInt);
                Context.FadeMusic(l_Volume, l_Fade);
            }
            finally
            {
                FreeAndNil(l_Eval);
            }
        }
        else
        {
            throw new EFURQRunTimeError(sWrongParams);
        }
    }
    
    private void HandleFPrint(in string aOperand)
    {
        NotAvailableWhileMenuBuild();
        OutTextToFile(aOperand);
    }
    
    private void HandleFPrintLn(in string aOperand)
    {
        NotAvailableWhileMenuBuild();
        OutTextToFile((aOperand + "\r\n"));
    }
    
    private void HandleImage(string aArgs)
    {
        string l_Filename;
        int[] l_Params;
        int l_PCount;
        TfurqLexer l_Lex;
        int l_LastParPos;
        string l_ParStr;
    
        NotAvailableWhileMenuBuild();
        FillChar(l_Params, SizeOf(l_Params), 0);
        aArgs = Trim(aArgs);
        l_Filename = "";
        l_PCount = 0;
        l_Lex = TfurqLexer.Create;
        try
        {
            l_Lex.Source = aArgs;
            while (true)
            {
                switch (l_Lex.Token)
                {
                    case etComma:
                        if (l_Filename == "")
                        {
                            l_Filename = Trim(Copy(aArgs, 1, (l_Lex.TokenStart - 1)));
                            l_LastParPos = (l_Lex.TokenStart + 1);
                        }
                        else
                        {
                            l_PCount++;
                            if (l_PCount > 4)
                            {
                                break;
                            }
                            l_ParStr = Copy(aArgs, l_LastParPos, (l_Lex.TokenStart - l_LastParPos));
                            l_Params[l_PCount] = StrToIntDef(l_ParStr, 0);
                            l_LastParPos = (l_Lex.TokenStart + 1);
                        }
                        break;
                    case etEOF:
                        if (l_Filename == "")
                        {
                            l_Filename = aArgs;
                        }
                        else
                        {
                            l_PCount++;
                            if (l_PCount > 4)
                            {
                                break;
                            }
                            l_ParStr = Copy(aArgs, l_LastParPos, MaxInt);
                            l_Params[l_PCount] = StrToIntDef(l_ParStr, 0);
                        }
                        break;
                        break;
                }
                l_Lex.NextToken();
            }
        }
        finally
        {
            global::FireURQ.Runtime.TObject.Free(l_Lex);
        }
        ((Tf2Context)(f_CurContext)).OutPicture(l_Filename, l_Params[1], l_Params[2], l_Params[3], l_Params[4]);
    }
    
    private void HandleNewFile(in string aOperand)
    {
        string l_FN;
    
        NotAvailableWhileMenuBuild();
        l_FN = Trim(AnsiLowerCase(aOperand));
        if (l_FN != "")
        {
            Context.Variables[c_fp_filename] = l_FN;
            DeleteFile(Context.FpFilename);
        }
    }
    
    private void HandleVoice(string aOperand)
    {
        NotAvailableWhileMenuBuild();
        aOperand = Trim(AnsiLowerCase(aOperand));
        if (aOperand == "stop")
        {
            Context.VoiceStop();
        }
        else
        {
            Context.VoicePlay(aOperand);
        }
    }
    
    private void HangleGssKill()
    {
        Context.KillSettingsStorage();
    }
    
    private void OutTextToFile(in string aText)
    {
        TFileStream l_F;
        ushort l_Mode;
    
        if (Context.FpFilename == "")
        {
            throw new EFURQRunTimeError("Не определён файл для вывода!");
        }
        if (aText == "")
        {
            return;
        }
        if (FileExists(Context.FpFilename))
        {
            l_Mode = fmOpenReadWrite;
        }
        else
        {
            l_Mode = fmCreate;
        }
        try
        {
            l_F = TFileStream.Create(Context.FpFilename, l_Mode);
            try
            {
                l_F.Seek(0, soFromEnd);
                l_F.Write(aText[1], Length(aText));
            }
            finally
            {
                global::FireURQ.Runtime.TObject.Free(l_F);
            }
        }
        catch (Exception)
        {
            throw EFURQRunTimeError.CreateFmt("Не удалось записать в файл %s", new HashSet<int>(new int[] { (int)(Context.FpFilename) }));
        }
    }
    
    private bool ParseDecorOperand(in string aOperand, ref string theDName, ref Tf2DecorParams theDParams)
    {
        TfurqLexer l_Lexer;
        bool result;
    
        result = false;
        l_Lexer = TfurqLexer.Create;
        try
        {
            l_Lexer.AllowSpacesInIdent = false;
            l_Lexer.SetSourceCustom(aOperand, cMaskedIdentSet);
            if (l_Lexer.Token != etCustom)
            {
                throw new EFURQRunTimeError(sDecorInvalidName);
            }
            theDName = l_Lexer.TokenValue;
            ParseDecorParams(l_Lexer, theDParams);
        }
        finally
        {
            global::FireURQ.Runtime.TObject.Free(l_Lexer);
        }
        return result;
    }
    
    private Tf2Context pm_GetContext()
    {
        Tf2Context result;
        result = ((Tf2Context)(f_CurContext));
        return result;
    }
    
